import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

test('actual pinned browser uses keyboard query completions safe results saved-filter form and live pause', {timeout: 35000}, async () => {
  const server = await testServer();
  let child;
  try {
    const api = server.agent();
    const auth = await api('POST', '/auth/signup', {name: 'Browser Owner', email: 'browser@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'Search browser'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'FIND', name: 'Browser project'})).data.project;
    const label = (await api('POST', '/projects/' + project.id + '/labels', {name: 'Ship today'})).data.label;
    const issue = (await api('POST', '/projects/' + project.id + '/issues', {title: 'Keyboard search', description: '<script>window.__searchInjected=true</script>', priority: 3, labelIds: [label.id]})).data.issue;
    const settings = {url: server.url, cookie: auth.cookie, orgId: org.id, issueId: issue.id};
    const result = await new Promise((resolve, reject) => {
      child = spawn('/usr/bin/python3', [fileURLToPath(new URL('./search-browser.py', import.meta.url)), JSON.stringify(settings)], {detached: true});
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {
        try {process.kill(-child.pid, 'SIGKILL');} catch {}
        reject(new Error('Browser process exceeded bounded deadline'));
      }, 30000);
      child.stdout.on('data', value => stdout += value);
      child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {clearTimeout(timer); resolve({code, stdout, stderr});});
    });
    assert.equal(result.code, 0, result.stderr);
    const flags = JSON.parse(result.stdout.trim());
    for (const name of ['keyboardCompletion', 'compoundResults', 'escapedHighlight', 'savedFilter', 'livePause', 'typedBuilder', 'staleConflict', 'accessLossCustody']) assert.equal(flags[name], true, name);
    const filters = (await api('GET', '/filters?orgId=' + org.id)).data.items;
    assert.equal(filters.length, 0);
  } finally {
    if (child?.pid) {try {process.kill(-child.pid, 'SIGKILL');} catch {}}
    await server.close();
  }
});
